To add a user sorting feature based on fields and direction, I used zustand for the global state management of the application.

These are the stores that I created for the global state management:

useDirectionStore for managing the directions:

```
import { create } from "zustand";
import { Field } from "./useFieldStore";

export interface Direction extends Field {}


interface State {
  direction: Direction;
  setDirection: (direction: Direction) => void;
}

export const useDirectionStore = create<State>((set) => ({
  direction: { label: "Ascending", value: "ascending" },
  setDirection: (direction: Direction) => set({ direction }),
}));
```

useFieldStore for managing the fields:

```
import { create } from "zustand";

export interface Field {
  label: string;
  value: string;
}

interface State {
  field: Field;
  setField: (field: Field) => void;
}

const useFieldStore = create<State>((set) => ({
  field: { label: "Name", value: "name" },
  setField: (field) => set({ field }),
}));

export default useFieldStore;
```

Then I added this code to handle the changes when the user selects a different field or direction in the controls.tsx file:

```
const { setField } = useFieldStore();
const { setDirection } = useDirectionStore();

const handleFieldChange = (selectedField: unknown) => {
  setField(selectedField as Field);
};

const handleDirection = (selectedDirection: unknown) => {
  setDirection(selectedDirection as Direction);
};
```

I used the global state of field and direction from the stores in zustand which will be used inside a useEffect to track it's changes:

```
const { field } = useFieldStore();
  const { direction } = useDirectionStore();

  useEffect(() => {
    const handleFieldChange = () => {
      if (field.value === "name") {
        setUsersList(
          [...usersList].sort((a, b) => {
            const comparison = a.name.localeCompare(b.name);
            return direction.value === "ascending" ? comparison : -comparison;
          })
        );
      } else if (field.value === "company") {
        setUsersList(
          [...usersList].sort((a, b) => {
            const comparison = a.company.name.localeCompare(b.company.name);
            return direction.value === "ascending" ? comparison : -comparison;
          })
        );
      } else {
        setUsersList(
          [...usersList].sort((a, b) => {
            const comparison = a.email.localeCompare(b.email);
            return direction.value === "ascending" ? comparison : -comparison;
          })
        );
      }
    };

    handleFieldChange();
  }, [field]);

  useEffect(() => {
    const handleDirectionChange = () => {
      if (field.value == "name") {
        if (direction.value == "ascending") {
          setUsersList(
            [...usersList].sort((a, b) => a.name.localeCompare(b.name))
          );
        } else {
          setUsersList(
            [...usersList].sort((a, b) => b.name.localeCompare(a.name))
          );
        }
      } else if (field.value == "company") {
        if (direction.value == "ascending") {
          setUsersList(
            [...usersList].sort((a, b) =>
              a.company.name.localeCompare(b.company.name)
            )
          );
        } else {
          setUsersList(
            [...usersList].sort((a, b) =>
              b.company.name.localeCompare(a.company.name)
            )
          );
        }
      } else if (field.value == "email") {
        if (direction.value == "ascending") {
          setUsersList(
            [...usersList].sort((a, b) => a.email.localeCompare(b.email))
          );
        } else {
          setUsersList(
            [...usersList].sort((a, b) => b.email.localeCompare(a.email))
          );
        }
      }
    };

    handleDirectionChange();
  }, [direction]);

```



